const clean=s=>s.toLowerCase().replace(/\.[lr]\.\d+$|\.\d+$/g,'').replace(/ muscle$/,'').trim();
const cards=new Map(rows.map(([name,normal,origin,insertion,nerve,source])=>[clean(name),{normal,origin,insertion,nerve,source}]));
const aliases={'biceps femoris long':'long head of biceps femoris','biceps femoris long head':'long head of biceps femoris','biceps femoris short':'short head of biceps femoris','biceps femoris short head':'short head of biceps femoris','gastrocnemius medial':'medial head of gastrocnemius','gastrocnemius lateral':'lateral head of gastrocnemius','peroneus longus':'fibularis longus'};
export function muscleStudy(r){if(r.layer!=='muscular')return null;const n=clean(r.name);return cards.get(aliases[n]||n)||null;}
export const muscleStudyCount=cards.size;
